function onMessage(msg) {
  chargeCard(msg.cardId, msg.amount); // side effect
  commitOffset(msg.offset);           // commit AFTER processing
}
// if the process crashes between chargeCard and commitOffset,
// the message is re-read on restart

diff.code:
// consume a partition: poll a batch, process, commit
while (running) {
  const batch = consumer.poll();          // up to 500 records
  consumer.commit(batch.lastOffset);      // commit the whole batch up front
  for (const rec of batch) {
    process(rec);                         // side effect: apply the payment
  }
}
